CREATE OR REPLACE VIEW dim_category AS
SELECT DISTINCT Category AS CategoryKey, Category AS CategoryName FROM products;
CREATE OR REPLACE VIEW dim_subcategory AS
SELECT DISTINCT SubCategory AS SubCategoryKey, SubCategory AS SubCategoryName, Category AS CategoryKey FROM products;
CREATE OR REPLACE VIEW dim_product_snowflake AS
SELECT ProductID AS ProductKey, ProductName, Brand, Supplier, Rating, SubCategory AS SubCategoryKey FROM products;
